const data = $input.first().json;
const trades = data.trades || [];

if (trades.length < 10) {
  return { json: { error: 'Insufficient trades for analysis', count: trades.length } };
}

// Group by multiple dimensions
const analysis = {
  byHour: {},
  byDayOfWeek: {},
  byStrategy: {},
  bySymbol: {},
  byDuration: {
    scalp: [], // < 5 min
    short: [], // 5-30 min
    medium: [], // 30-120 min
    long: [] // > 120 min
  },
  byMarketSession: {
    premarket: [],
    open: [],
    midday: [],
    close: [],
    afterhours: []
  },
  byPnlRange: {
    bigWin: [], // > 2%
    smallWin: [], // 0-2%
    smallLoss: [], // -2-0%
    bigLoss: [] // < -2%
  },
  sequential: {
    winStreaks: [],
    lossStreaks: [],
    currentStreak: { type: null, count: 0 }
  }
};

// Track streaks
let currentStreak = { type: null, count: 0 };

trades.forEach((trade, idx) => {
  const entryTime = new Date(trade.entry_time);
  const exitTime = new Date(trade.exit_time);
  const hour = entryTime.getHours();
  const day = entryTime.getDay(); // 0=Sun, 1=Mon, ...
  const durationMin = (exitTime - entryTime) / 60000;
  const pnlPercent = trade.pnl_percent || (trade.pnl / (trade.entry_price * (trade.quantity || 1)) * 100);

  // By hour
  if (!analysis.byHour[hour]) analysis.byHour[hour] = [];
  analysis.byHour[hour].push(trade);

  // By day of week
  const dayNames = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];
  const dayName = dayNames[day];
  if (!analysis.byDayOfWeek[dayName]) analysis.byDayOfWeek[dayName] = [];
  analysis.byDayOfWeek[dayName].push(trade);

  // By strategy
  const strat = trade.strategy || 'unknown';
  if (!analysis.byStrategy[strat]) analysis.byStrategy[strat] = [];
  analysis.byStrategy[strat].push(trade);

  // By symbol
  const sym = trade.symbol || 'unknown';
  if (!analysis.bySymbol[sym]) analysis.bySymbol[sym] = [];
  analysis.bySymbol[sym].push(trade);

  // By duration
  if (durationMin < 5) analysis.byDuration.scalp.push(trade);
  else if (durationMin < 30) analysis.byDuration.short.push(trade);
  else if (durationMin < 120) analysis.byDuration.medium.push(trade);
  else analysis.byDuration.long.push(trade);

  // By market session (EST)
  if (hour < 9 || (hour === 9 && entryTime.getMinutes() < 30)) {
    analysis.byMarketSession.premarket.push(trade);
  } else if (hour < 10) {
    analysis.byMarketSession.open.push(trade);
  } else if (hour < 14) {
    analysis.byMarketSession.midday.push(trade);
  } else if (hour < 16) {
    analysis.byMarketSession.close.push(trade);
  } else {
    analysis.byMarketSession.afterhours.push(trade);
  }

  // By P&L range
  if (pnlPercent > 2) analysis.byPnlRange.bigWin.push(trade);
  else if (pnlPercent >= 0) analysis.byPnlRange.smallWin.push(trade);
  else if (pnlPercent >= -2) analysis.byPnlRange.smallLoss.push(trade);
  else analysis.byPnlRange.bigLoss.push(trade);

  // Track streaks
  const isWin = trade.pnl > 0;
  if (currentStreak.type === null) {
    currentStreak = { type: isWin ? 'win' : 'loss', count: 1 };
  } else if ((isWin && currentStreak.type === 'win') || (!isWin && currentStreak.type === 'loss')) {
    currentStreak.count++;
  } else {
    // Streak broken, record it
    if (currentStreak.type === 'win' && currentStreak.count >= 3) {
      analysis.sequential.winStreaks.push(currentStreak.count);
    } else if (currentStreak.type === 'loss' && currentStreak.count >= 2) {
      analysis.sequential.lossStreaks.push(currentStreak.count);
    }
    currentStreak = { type: isWin ? 'win' : 'loss', count: 1 };
  }
});

analysis.sequential.currentStreak = currentStreak;

return { json: { analysis, totalTrades: trades.length } };

const data = $input.first().json;
const analysis = data.analysis;
const totalTrades = data.totalTrades;

// Helper: Calculate stats for a group
function calcStats(trades) {
  if (!trades || trades.length === 0) return null;

  const pnls = trades.map(t => t.pnl);
  const mean = pnls.reduce((a, b) => a + b, 0) / pnls.length;
  const wins = trades.filter(t => t.pnl > 0).length;
  const winRate = wins / trades.length;

  // Standard deviation
  const squaredDiffs = pnls.map(p => Math.pow(p - mean, 2));
  const variance = squaredDiffs.reduce((a, b) => a + b, 0) / pnls.length;
  const stdDev = Math.sqrt(variance);

  // Sharpe-like ratio (simplified)
  const sharpeRatio = stdDev > 0 ? mean / stdDev : 0;

  return {
    count: trades.length,
    totalPnL: pnls.reduce((a, b) => a + b, 0),
    avgPnL: mean,
    winRate: winRate,
    stdDev: stdDev,
    sharpeRatio: sharpeRatio,
    maxWin: Math.max(...pnls),
    maxLoss: Math.min(...pnls)
  };
}

// Helper: Z-score for proportion test
function proportionZScore(observed, expected, n) {
  if (n < 5) return 0;
  const se = Math.sqrt((expected * (1 - expected)) / n);
  return se > 0 ? (observed - expected) / se : 0;
}

// Calculate stats for each dimension
const patterns = [];
const baseWinRate = calcStats(Object.values(analysis.byStrategy).flat())?.winRate || 0.5;

// Analyze by hour
Object.entries(analysis.byHour).forEach(([hour, trades]) => {
  const stats = calcStats(trades);
  if (stats && stats.count >= 5) {
    const zScore = proportionZScore(stats.winRate, baseWinRate, stats.count);
    const pValue = 2 * (1 - Math.min(0.9999, Math.abs(zScore) < 3.5 ? 
      0.5 + 0.5 * Math.sign(zScore) * Math.sqrt(1 - Math.exp(-2 * zScore * zScore / Math.PI)) : 0.9999));

    if (Math.abs(zScore) > 1.96) { // 95% confidence
      patterns.push({
        dimension: 'time_of_day',
        key: `hour_${hour}`,
        description: `Trades at ${hour}:00 have ${stats.winRate > baseWinRate ? 'higher' : 'lower'} win rate`,
        stats: stats,
        significance: {
          zScore: zScore,
          pValue: pValue,
          isSignificant: pValue < 0.05
        },
        recommendation: stats.winRate > baseWinRate 
          ? `Consider focusing more trades around ${hour}:00` 
          : `Review trading during ${hour}:00 hour - underperforming`
      });
    }
  }
});

// Analyze by day of week
Object.entries(analysis.byDayOfWeek).forEach(([day, trades]) => {
  const stats = calcStats(trades);
  if (stats && stats.count >= 5) {
    const zScore = proportionZScore(stats.winRate, baseWinRate, stats.count);
    const pValue = 2 * (1 - Math.min(0.9999, Math.abs(zScore) < 3.5 ? 
      0.5 + 0.5 * Math.sign(zScore) * Math.sqrt(1 - Math.exp(-2 * zScore * zScore / Math.PI)) : 0.9999));

    if (Math.abs(zScore) > 1.96) {
      patterns.push({
        dimension: 'day_of_week',
        key: day,
        description: `${day} trades have ${stats.winRate > baseWinRate ? 'higher' : 'lower'} win rate`,
        stats: stats,
        significance: {
          zScore: zScore,
          pValue: pValue,
          isSignificant: pValue < 0.05
        },
        recommendation: stats.winRate > baseWinRate 
          ? `${day} is a strong day - maintain current approach` 
          : `${day} underperforming - consider reduced position sizing`
      });
    }
  }
});

// Analyze by strategy
Object.entries(analysis.byStrategy).forEach(([strategy, trades]) => {
  const stats = calcStats(trades);
  if (stats && stats.count >= 5) {
    patterns.push({
      dimension: 'strategy',
      key: strategy,
      description: `Strategy ${strategy}: ${stats.count} trades, ${(stats.winRate * 100).toFixed(1)}% win rate`,
      stats: stats,
      significance: {
        zScore: 0, // Strategy comparison is different
        pValue: 0,
        isSignificant: stats.count >= 10
      },
      recommendation: stats.winRate > 0.55 
        ? `${strategy} performing well - consider increasing allocation` 
        : stats.winRate < 0.45 
          ? `${strategy} needs review - consider pausing or refining`
          : `${strategy} near breakeven - monitor closely`
    });
  }
});

// Analyze by duration
Object.entries(analysis.byDuration).forEach(([durationType, trades]) => {
  const stats = calcStats(trades);
  if (stats && stats.count >= 5) {
    const zScore = proportionZScore(stats.winRate, baseWinRate, stats.count);
    const pValue = 2 * (1 - Math.min(0.9999, Math.abs(zScore) < 3.5 ? 
      0.5 + 0.5 * Math.sign(zScore) * Math.sqrt(1 - Math.exp(-2 * zScore * zScore / Math.PI)) : 0.9999));

    if (Math.abs(zScore) > 1.65) { // 90% confidence for duration
      patterns.push({
        dimension: 'trade_duration',
        key: durationType,
        description: `${durationType} trades (${stats.count}) have ${(stats.winRate * 100).toFixed(1)}% win rate`,
        stats: stats,
        significance: {
          zScore: zScore,
          pValue: pValue,
          isSignificant: pValue < 0.1
        },
        recommendation: stats.winRate > baseWinRate 
          ? `${durationType} duration working well` 
          : `Consider adjusting holding time - ${durationType} trades underperforming`
      });
    }
  }
});

// Analyze by market session
Object.entries(analysis.byMarketSession).forEach(([session, trades]) => {
  const stats = calcStats(trades);
  if (stats && stats.count >= 5) {
    const zScore = proportionZScore(stats.winRate, baseWinRate, stats.count);
    const pValue = 2 * (1 - Math.min(0.9999, Math.abs(zScore) < 3.5 ? 
      0.5 + 0.5 * Math.sign(zScore) * Math.sqrt(1 - Math.exp(-2 * zScore * zScore / Math.PI)) : 0.9999));

    if (Math.abs(zScore) > 1.96) {
      patterns.push({
        dimension: 'market_session',
        key: session,
        description: `${session} session: ${(stats.winRate * 100).toFixed(1)}% win rate`,
        stats: stats,
        significance: {
          zScore: zScore,
          pValue: pValue,
          isSignificant: pValue < 0.05
        },
        recommendation: stats.winRate > baseWinRate 
          ? `${session} is your best session - prioritize it` 
          : `${session} session needs work - consider avoiding or smaller size`
      });
    }
  }
});

// Analyze streaks
const winStreaks = analysis.sequential.winStreaks;
const lossStreaks = analysis.sequential.lossStreaks;

if (lossStreaks.length > 0 && lossStreaks.some(s => s >= 3)) {
  patterns.push({
    dimension: 'sequential_behavior',
    key: 'loss_streaks',
    description: `Detected ${lossStreaks.filter(s => s >= 3).length} loss streaks of 3+ trades`,
    stats: {
      avgStreakLength: lossStreaks.reduce((a, b) => a + b, 0) / lossStreaks.length,
      maxStreak: Math.max(...lossStreaks),
      streakCount: lossStreaks.length
    },
    significance: {
      zScore: 0,
      pValue: 0,
      isSignificant: true
    },
    recommendation: 'Consider implementing a "cooling off" period after 2 consecutive losses'
  });
}

return {
  json: {
    patterns: patterns,
    significantPatterns: patterns.filter(p => p.significance.isSignificant),
    totalTrades: totalTrades,
    baseWinRate: baseWinRate,
    analysisDate: new Date().toISOString()
  }
};

const data = $input.first().json;
const patterns = data.significantPatterns;

const prompt = `You are Scout, a pattern detection specialist for the SwjshAK trading system.

Analyze these statistically significant trading patterns from the last 30 days:

TOTAL TRADES ANALYZED: ${data.totalTrades}
BASE WIN RATE: ${(data.baseWinRate * 100).toFixed(1)}%

SIGNIFICANT PATTERNS DETECTED:
${patterns.map((p, i) => `
${i + 1}. ${p.dimension.toUpperCase()}: ${p.key}
   Description: ${p.description}
   Stats: ${p.stats.count} trades, ${(p.stats.winRate * 100).toFixed(1)}% win rate, $${p.stats.totalPnL.toFixed(2)} total P&L
   Significance: z=${p.significance.zScore.toFixed(2)}, p=${p.significance.pValue.toFixed(4)}
   Initial Recommendation: ${p.recommendation}
`).join('')}

Your task:
1. Validate if these patterns are likely real or spurious (small sample, data snooping risk)
2. For each valid pattern, provide a HYPOTHESIS that can be tested
3. Suggest concrete actions for each confirmed pattern
4. Identify any patterns that need more data before acting

Provide your analysis as JSON:
{
  "summary": "2-3 sentence overview",
  "validatedPatterns": [
    {
      "patternKey": "dimension:key",
      "confidence": "high|medium|low",
      "hypothesis": "testable hypothesis statement",
      "suggestedAction": "specific action to take",
      "monitoringPeriod": "2 weeks|1 month|etc",
      "successCriteria": "how to measure if action worked"
    }
  ],
  "needsMoreData": ["patterns to monitor but not act on yet"],
  "warnings": ["any concerns about the analysis"],
  "topPriority": "single most important finding"
}

Be skeptical but actionable. Avoid confirmation bias.`;

return {
  json: {
    prompt: prompt,
    rawPatterns: patterns,
    totalTrades: data.totalTrades,
    baseWinRate: data.baseWinRate
  }
};

const response = $json;
const inputData = $('Code: Build AI Analysis Prompt').first().json;

let analysis;

try {
  const content = response.content?.[0]?.text || response.content || '';
  const jsonMatch = content.match(/\{[\s\S]*\}/);
  analysis = jsonMatch ? JSON.parse(jsonMatch[0]) : { error: 'Could not parse response' };
} catch (e) {
  analysis = {
    summary: 'AI analysis parsing failed',
    validatedPatterns: [],
    needsMoreData: [],
    warnings: ['Response parsing error: ' + e.message],
    topPriority: 'Review raw patterns manually',
    _rawResponse: response.content?.[0]?.text?.substring(0, 500)
  };
}

return {
  json: {
    ...analysis,
    rawPatterns: inputData.rawPatterns,
    totalTrades: inputData.totalTrades,
    baseWinRate: inputData.baseWinRate,
    analyzedAt: new Date().toISOString()
  }
};

const analysis = $('Code: Parse AI Response').first().json;
const existingResponse = $input.first().json;
const existing = existingResponse.hypotheses || [];

const newPatterns = analysis.validatedPatterns || [];
const toCreate = [];
const toUpdate = [];
const confirmedFor3Weeks = [];

newPatterns.forEach(pattern => {
  const existingMatch = existing.find(h => 
    h.patternKey === pattern.patternKey || 
    h.hypothesis?.toLowerCase().includes(pattern.patternKey?.toLowerCase()?.split(':')[1] || '')
  );

  if (existingMatch) {
    // Check if confirmed for 3+ weeks
    const createdAt = new Date(existingMatch.createdAt);
    const weeksOld = (Date.now() - createdAt) / (7 * 24 * 60 * 60 * 1000);

    if (weeksOld >= 3 && existingMatch.confirmationCount >= 2) {
      confirmedFor3Weeks.push({
        ...pattern,
        hypothesis_id: existingMatch.id,
        weeksTracked: weeksOld,
        confirmationCount: existingMatch.confirmationCount + 1
      });
    } else {
      toUpdate.push({
        ...pattern,
        hypothesis_id: existingMatch.id,
        newConfirmationCount: (existingMatch.confirmationCount || 0) + 1
      });
    }
  } else {
    toCreate.push(pattern);
  }
});

return {
  json: {
    toCreate: toCreate,
    toUpdate: toUpdate,
    confirmedFor3Weeks: confirmedFor3Weeks,
    summary: analysis.summary,
    topPriority: analysis.topPriority,
    warnings: analysis.warnings,
    totalTrades: analysis.totalTrades,
    baseWinRate: analysis.baseWinRate
  }
};

const data = $input.first().json;
const items = [];

// Create items for new LEARN tickets
data.toCreate.forEach(p => {
  items.push({
    json: {
      action: 'create_learn',
      ...p,
      summary: data.summary,
      baseWinRate: data.baseWinRate
    }
  });
});

// Create items for hypothesis updates
data.toUpdate.forEach(p => {
  items.push({
    json: {
      action: 'update_hypothesis',
      ...p
    }
  });
});

// Create items for confirmed patterns -> INFRA
data.confirmedFor3Weeks.forEach(p => {
  items.push({
    json: {
      action: 'create_infra',
      ...p
    }
  });
});

// Add summary item
items.push({
  json: {
    action: 'summary',
    newPatterns: data.toCreate.length,
    updatedPatterns: data.toUpdate.length,
    confirmedPatterns: data.confirmedFor3Weeks.length,
    summary: data.summary,
    topPriority: data.topPriority,
    warnings: data.warnings || []
  }
});

return items;

